import type { CallJob } from "./call-job";
import { job, registry, startJob, waitForTurn } from "./jobs";
import type { Env } from "./types";

// Minimal stateless MCP server (Streamable HTTP, JSON responses only).
const INSTRUCTIONS = `Make phone calls with a voice agent that sounds like a person.
1. phonecall_start with the number and a brief: the goal, facts it may share, limits, and what counts as done.
2. phonecall_watch until it returns. "input_request": the agent is on the line waiting for your answer, so reply within about a minute with phonecall_reply, then watch again. "running": watch again. "done": the report is included.
Use simulate (a persona) for a test call where a second AI plays the other side and nobody is dialed.`;

const TOOLS = [
  {
    name: "phonecall_start",
    description: "Start a phone call. Returns a job_id right away; then call phonecall_watch.",
    inputSchema: {
      type: "object",
      properties: {
        to: { type: "string", description: "Number to call in E.164 form, like +14155550100. Omit when simulating." },
        brief: { type: "string", description: "What to get done: goal, facts the caller may share, limits (what not to agree to), what counts as done." },
        for: { type: "string", description: "Who the call is on behalf of (defaults to the server's PRINCIPAL_NAME)." },
        as: { type: "string", description: "Name the caller gives (default Sam)." },
        voice: { type: "string", enum: ["eve", "ara", "rex", "sal", "leo"] },
        max_minutes: { type: "number", description: "Hard limit on call length, 1-30 (default 10)." },
        answer_timeout: { type: "number", description: "Seconds the caller waits for your reply to a question (default 60)." },
        simulate: { type: "string", description: "Test only: persona for a second AI that plays the person being called. Nobody is dialed." },
      },
      required: ["brief"],
    },
  },
  {
    name: "phonecall_watch",
    description: "Wait for the call's next question or its end (up to ~45s). Returns type input_request (answer with phonecall_reply), running (watch again) or done (with the report). Pass the returned cursor back to only see new progress.",
    inputSchema: {
      type: "object",
      properties: { job_id: { type: "string" }, cursor: { type: "number" }, timeout_seconds: { type: "number", description: "Max wait, up to 50 (default 45)." } },
      required: ["job_id"],
    },
  },
  {
    name: "phonecall_reply",
    description: "Answer the agent's question while the call is live. The agent relays it to the other person right away.",
    inputSchema: {
      type: "object",
      properties: { job_id: { type: "string" }, question_id: { type: "string" }, answer: { type: "string" } },
      required: ["job_id", "question_id", "answer"],
    },
  },
  {
    name: "phonecall_report",
    description: "Get a call's summary, questions and full transcript.",
    inputSchema: { type: "object", properties: { job_id: { type: "string" } }, required: ["job_id"] },
  },
  {
    name: "phonecall_list",
    description: "List recent calls.",
    inputSchema: { type: "object", properties: { limit: { type: "number" } } },
  },
  {
    name: "phonecall_hangup",
    description: "End a call now.",
    inputSchema: { type: "object", properties: { job_id: { type: "string" } }, required: ["job_id"] },
  },
];

type Rpc = { jsonrpc: "2.0"; id?: string | number | null; method: string; params?: any };

export async function handleMcp(req: Request, env: Env, origin: string): Promise<Response> {
  if (req.method !== "POST") return new Response("method not allowed", { status: 405, headers: { Allow: "POST" } });
  let body: Rpc | Rpc[];
  try {
    body = await req.json();
  } catch {
    return Response.json({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "parse error" } }, { status: 400 });
  }
  const batch = Array.isArray(body) ? body : [body];
  const replies = (await Promise.all(batch.map((m) => handle(m, env, origin)))).filter((r) => r !== null);
  if (!replies.length) return new Response(null, { status: 202 });
  return Response.json(Array.isArray(body) ? replies : replies[0]);
}

async function handle(msg: Rpc, env: Env, origin: string) {
  if (msg.id === undefined) return null; // notification
  const ok = (result: unknown) => ({ jsonrpc: "2.0", id: msg.id, result });
  switch (msg.method) {
    case "initialize":
      return ok({
        protocolVersion: msg.params?.protocolVersion ?? "2025-06-18",
        capabilities: { tools: {} },
        serverInfo: { name: "phonecall", version: "0.1.0" },
        instructions: INSTRUCTIONS,
      });
    case "ping":
      return ok({});
    case "tools/list":
      return ok({ tools: TOOLS });
    case "tools/call":
      try {
        const result = await callTool(msg.params?.name, msg.params?.arguments ?? {}, env, origin);
        return ok({ content: [{ type: "text", text: JSON.stringify(result, null, 2) }], isError: !!(result as any)?.error });
      } catch (err) {
        return ok({ content: [{ type: "text", text: `error: ${String(err)}` }], isError: true });
      }
    default:
      return { jsonrpc: "2.0", id: msg.id, error: { code: -32601, message: `unknown method ${msg.method}` } };
  }
}

async function callTool(name: string, a: Record<string, any>, env: Env, origin: string): Promise<unknown> {
  switch (name) {
    case "phonecall_start": {
      const r = await startJob(env, origin, { ...a, principal: a.for, agent_name: a.as });
      return "error" in r ? { error: r.error } : { job_id: r.job_id, next: "Call phonecall_watch with this job_id." };
    }
    case "phonecall_watch": {
      const timeout = Math.min(Math.max(Number(a.timeout_seconds ?? 45), 1), 50) * 1000;
      return (await waitForTurn(env, a.job_id, Number(a.cursor ?? 0), timeout)) ?? { error: "unknown job" };
    }
    case "phonecall_reply":
      return job(env, a.job_id).reply(a.question_id, String(a.answer ?? ""));
    case "phonecall_report": {
      const r = (await job(env, a.job_id).report()) as unknown as Awaited<ReturnType<CallJob["report"]>>;
      if (!r) return { error: "unknown job" };
      return {
        status: r.job.status,
        to: r.job.to,
        report: r.job.report ?? null,
        questions: r.questions.map((q) => ({ id: q.id, question: q.question, answer: q.answer, status: q.status })),
        transcript: r.transcript.map((t) => `${t.who === "agent" ? r.job.agentName : "Them"}: ${t.text}`).join("\n"),
      };
    }
    case "phonecall_list":
      return registry(env).list(Number(a.limit ?? 20));
    case "phonecall_hangup":
      return job(env, a.job_id).hangup();
    default:
      return { error: `unknown tool ${name}` };
  }
}

#!/usr/bin/env node
// One-time setup: registers your Twilio number with xAI's SIP service, stores the Worker's
// secrets with wrangler, and writes the CLI config to ~/.config/phonecall.
// Values can come from environment variables of the same name; anything missing is asked for.
import { spawnSync } from "node:child_process";
import { randomBytes, randomInt } from "node:crypto";
import { chmodSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { createInterface } from "node:readline/promises";

const simulate = !process.argv.includes("--no-sim");
const rl = createInterface({ input: process.stdin, output: process.stderr });

async function value(name, question, valid = () => true) {
  let v = process.env[name]?.trim();
  while (!v || !valid(v)) {
    if (v) console.error("  That doesn't look right, try again.");
    v = (await rl.question(`${question}: `)).trim();
  }
  return v;
}

function fail(message) {
  console.error(`\nsetup: ${message}`);
  process.exit(1);
}

const url = (await value("PHONECALL_URL", "Worker URL from `npx wrangler deploy` (https://phonecall.<you>.workers.dev)", (v) => v.startsWith("https://"))).replace(/\/$/, "");
const xaiKey = await value("XAI_API_KEY", "xAI API key");
const twilioSid = await value("TWILIO_ACCOUNT_SID", "Twilio Account SID (starts with AC)", (v) => v.startsWith("AC"));
const twilioToken = await value("TWILIO_AUTH_TOKEN", "Twilio Auth Token");
const number = await value("TWILIO_PHONE_NUMBER", "Twilio number to call from, like +14155550100", (v) => /^\+[1-9]\d{7,14}$/.test(v));
const principal = await value("PRINCIPAL_NAME", 'Your name, as the caller says it ("I\'m calling for ...")');
rl.close();

console.error("\nChecking Twilio...");
const tw = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${twilioSid}/IncomingPhoneNumbers.json?PhoneNumber=${encodeURIComponent(number)}`, {
  headers: { Authorization: `Basic ${Buffer.from(`${twilioSid}:${twilioToken}`).toString("base64")}` },
});
if (!tw.ok) fail(`Twilio rejected the credentials (HTTP ${tw.status}).`);
if (!(await tw.json()).incoming_phone_numbers?.length) fail(`${number} isn't a phone number on this Twilio account.`);

const sipUsername = `phonecall-${randomBytes(4).toString("hex")}`;
const sipPassword = [REDACTED]"hex");
const xai = (path, init = {}) => fetch(`https://api.x.ai${path}`, { ...init, headers: { Authorization: `Bearer ${xaiKey}`, "Content-Type": "application/json", ...init.headers } });

// Registers a number with xAI's SIP service and returns its webhook signing secret.
// A registration left over from an earlier run is replaced, since its secret can't be read back.
async function register(phone, name) {
  const body = JSON.stringify({
    origin: "byo_trunk",
    name,
    phone_number: phone,
    webhook: { name: "phonecall", url: `${url}/xai/webhook` },
    sip_auth: { auth_username: sipUsername, auth_password: sipPassword },
  });
  for (let attempt = 0; attempt < 2; attempt++) {
    const res = await xai("/v2/phone-numbers", { method: "POST", body });
    const data = await res.json().catch(() => ({}));
    if (res.ok) return data.webhook.dispatch_signing_secret;
    const list = await (await xai("/v2/phone-numbers")).json().catch(() => ({}));
    const existing = list.phone_numbers?.find((n) => n.phone_number === phone);
    if (attempt > 0 || !existing) fail(`xAI didn't register ${phone} (HTTP ${res.status}): ${JSON.stringify(data).slice(0, 300)}`);
    console.error(`  Replacing the earlier xAI registration for ${phone}`);
    await xai(`/v2/phone-numbers/${existing.phone_number_id}`, { method: "DELETE" });
  }
}

// NANP reserves 555-0100 to 555-0199 for fiction, so the simulator number can never be a real line.
function fictionalNumber() {
  let areaCode;
  do areaCode = `${randomInt(2, 10)}${randomInt(0, 10)}${randomInt(0, 10)}`;
  while (areaCode.endsWith("11"));
  return `+1${areaCode}55501${String(randomInt(0, 100)).padStart(2, "0")}`;
}

console.error(`Registering ${number} with xAI...`);
const webhookSecrets = [await register(number, "phonecall")];
let simNumber;
if (simulate) {
  simNumber = fictionalNumber();
  console.error(`Registering ${simNumber} for simulated calls...`);
  webhookSecrets.push(await register(simNumber, "phonecall simulator"));
}

// Reuse PHONECALL_TOKEN when given, so connected CLIs and MCP clients keep working after a re-run.
const phonecallToken = [REDACTED] || randomBytes(32).toString("hex");
const secrets = {
  XAI_API_KEY: xaiKey,
  XAI_WEBHOOK_SECRET: [REDACTED]","),
  SIP_USERNAME: sipUsername,
  SIP_PASSWORD: sipPassword,
  TWILIO_ACCOUNT_SID: twilioSid,
  TWILIO_AUTH_TOKEN: twilioToken,
  TWILIO_PHONE_NUMBER: number,
  PRINCIPAL_NAME: principal,
  PHONECALL_TOKEN: [REDACTED],
  ...(simNumber ? { SIM_NUMBER: simNumber } : {}),
};

console.error("Storing Worker secrets...");
const dir = mkdtempSync(join(tmpdir(), "phonecall-"));
const file = join(dir, "secrets.json");
writeFileSync(file, JSON.stringify(secrets), { mode: 0o600 });
const [cmd, ...args] = (process.env.WRANGLER ?? "npx wrangler").split(" ");
const result = spawnSync(cmd, [...args, "secret", "bulk", file], { stdio: ["ignore", "inherit", "inherit"] });
rmSync(dir, { recursive: true, force: true });
if (result.status !== 0) fail("wrangler couldn't store the secrets. Run `npx wrangler login`, then `npm run setup` again.");

const configDir = join(homedir(), ".config", "phonecall");
mkdirSync(configDir, { recursive: true, mode: 0o700 });
for (const [name, content] of [
  ["config.json", `${JSON.stringify({ url, token: [REDACTED] }, null, 2)}\n`],
  ["token", phonecallToken],
]) {
  writeFileSync(join(configDir, name), content, { mode: 0o600 });
  chmodSync(join(configDir, name), 0o600);
}

console.log(`
Done. phonecall is live at ${url}

CLI config: ~/.config/phonecall/config.json
MCP token:  [REDACTED]

Try a simulated call (nobody is dialed):
  phonecall call --simulate "You run the counter at a busy pizza place." \\
    --brief "Order a large pepperoni for pickup at 7pm." --watch
`);

import type { CallJob } from "./call-job";
import type { Registry } from "./registry";

export interface Env {
  CALL_JOB: DurableObjectNamespace<CallJob>;
  REGISTRY: DurableObjectNamespace<Registry>;
  PHONECALL_TOKEN: string;
  XAI_API_KEY: string;
  XAI_WEBHOOK_SECRET: string;
  SIP_USERNAME: string;
  SIP_PASSWORD: string;
  TWILIO_ACCOUNT_SID: string;
  TWILIO_AUTH_TOKEN: string;
  TWILIO_PHONE_NUMBER: string;
  // Who calls are made for, unless a call says otherwise.
  PRINCIPAL_NAME?: string;
  // A second xAI SIP number for simulated calls. Optional.
  SIM_NUMBER?: string;
  AGENT_NAME?: string;
  VOICE?: string;
  SUMMARY_MODEL?: string;
}

export type JobStatus = "dialing" | "ringing" | "connected" | "ended" | "done";

export interface Job {
  id: string;
  to: string;
  brief: string;
  principal: string;
  agentName: string;
  voice: string;
  maxMinutes: number;
  answerTimeoutSec: number;
  // Persona for a simulated callee; when set, the call goes to a second Grok agent instead of a phone.
  simulate?: string;
  origin: string;
  status: JobStatus;
  createdAt: number;
  twilioCallSid?: string;
  twilioStatus?: string;
  xaiCallId?: string;
  simCallId?: string;
  answeredAt?: number;
  endedAt?: number;
  durationSec?: number;
  endCall?: { outcome: string; notes?: string };
  report?: Report;
}

export interface Report {
  outcome: string;
  summary: string;
  details: Record<string, string>;
  commitments: string[];
  follow_ups: string[];
}

export interface Question {
  id: string;
  question: string;
  status: "pending" | "answered" | "timed_out";
  answer: string | null;
  askedAt: number;
  answeredAt: number | null;
}

export interface JobEvent {
  seq: number;
  at: number;
  type: string;
  // `any` rather than `unknown`: Durable Object RPC types collapse `unknown` to `never`.
  data: Record<string, any>;
}

import { DurableObject } from "cloudflare:workers";
import type { Env, JobStatus } from "./types";

export type JobRow = {
  id: string;
  to: string;
  status: JobStatus;
  created_at: number;
  attached: number;
  brief: string;
};

// One instance ("main") that lists jobs and matches incoming SIP legs to jobs without a header.
export class Registry extends DurableObject<Env> {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.storage.sql.exec(`CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, "to" TEXT, status TEXT, created_at INTEGER, attached INTEGER DEFAULT 0, brief TEXT)`);
  }

  add(id: string, to: string, brief: string) {
    this.ctx.storage.sql.exec(`INSERT INTO jobs (id, "to", status, created_at, brief) VALUES (?, ?, 'dialing', ?, ?)`, id, to, Date.now(), brief.slice(0, 200));
  }

  update(id: string, fields: { status?: JobStatus; attached?: boolean }) {
    if (fields.status) this.ctx.storage.sql.exec(`UPDATE jobs SET status = ? WHERE id = ?`, fields.status, id);
    if (fields.attached) this.ctx.storage.sql.exec(`UPDATE jobs SET attached = 1 WHERE id = ?`, id);
  }

  list(limit: number): JobRow[] {
    return this.ctx.storage.sql.exec<JobRow>(`SELECT * FROM jobs ORDER BY created_at DESC LIMIT ?`, limit).toArray();
  }

  // Most recent live job whose voice agent hasn't joined yet.
  unattached(): string | null {
    const row = this.ctx.storage.sql
      .exec<{ id: string }>(`SELECT id FROM jobs WHERE attached = 0 AND status IN ('dialing', 'ringing', 'connected') AND created_at > ? ORDER BY created_at DESC LIMIT 1`, Date.now() - 10 * 60_000)
      .toArray()[0];
    return row?.id ?? null;
  }
}

import type { Job } from "./types";

// Grok Voice follows the section order from xAI's speech-to-speech prompting guide.
export function callerInstructions(job: Job): string {
  const { agentName: me, principal: them } = job;
  return `## Role & Persona
You are ${me}, making a quick phone call on behalf of ${them}. You sound like a relaxed, capable person who makes calls like this all the time: friendly, direct and a little casual. You are the caller, not a receptionist or a support agent.

## Objective
Get this done for ${them}:

${job.brief.trim()}

Stick to what is in that brief. Once it is done, or clearly can't be done on this call, wrap up.

## Conversation Flow
- Opening: the other person has just picked up. Say hi, who you are and why you're calling in one easy sentence, like "Hi, this is ${me}, I'm calling for ${them}, I was hoping to..." If they already started talking, answer them first.
- Phone menus: if you hear a recorded menu, listen to the options and use \`send_dtmf\` to press the right key. If nothing fits, press 0 or say "representative". Don't talk over the recording.
- Hold: if they put you on hold or you hear hold music, stay quiet until a person talks to you, then briefly say who you are again.
- Voicemail: if you reach voicemail or an answering machine, don't leave a message unless the brief says to. Call \`end_call\` with outcome "voicemail".
- Wrong place: if this isn't the right place or person, ask once where you should call instead, then wrap up.
- Something you don't know or can't decide: don't start answering it. Say a short natural line like "one sec, let me just check on that" and call \`request_input\` with a clear, self-contained question for ${them}. Then stay quiet unless they talk to you.
- While you wait for ${them}'s answer: if they ask or press you, say something short like "yeah, sorry, still checking, one sec" and keep chatting normally. Keep waiting. Only say you'll get back to them on that part if \`check_messages\` tells you ${them} didn't answer in time.
- When \`check_messages\` returns ${them}'s answer, use it in your very next sentence, the way a person relays it ("okay, Saturday at seven works").
- Wrapping up: once they've confirmed, repeat the one or two key details once (day, time, name, price, confirmation number), say a short goodbye like "perfect, thanks so much, bye", and call \`end_call\` in that same turn.

## Guardrails & Escalation
- Only share details the brief gives you, and only when they are needed. Never make up names, numbers, prices, dates or details.
- Never agree to pay, put down a deposit, give card or bank details, or sign up for anything unless the brief explicitly allows it. If they need any of that, use \`request_input\`.
- If someone sincerely asks whether you're a real person, a bot or an AI, be honest: say you're an AI assistant calling for ${them}, then carry on normally. Don't bring it up otherwise.
- If they ask you not to call again or don't want to talk to an AI, apologize briefly, say goodbye and call \`end_call\` with outcome "refused".

## Voice & Communication Style
- Talk like a normal person on the phone: short sentences, contractions, plain words. One or two sentences per turn.
- Use small natural reactions and vary them: "yeah", "okay", "oh nice", "gotcha", "perfect", "ah, okay".
- An occasional "um" or "so" is fine where a person would say it. Don't overdo it.
- NEVER use customer-service phrases like "I'd be happy to", "certainly", "absolutely", "great question", "is there anything else I can help you with" or "I understand".
- Don't repeat back everything they say. Confirm only the details that matter.
- Let them finish. If they talk over you, stop and listen.
- If you didn't catch something, ask casually: "sorry, what was that?"
- Say phone numbers in natural groups, like "four-one-five, five-five-five, zero-one-nine-nine". Spell names letter by letter only when asked.
- Spoken words only: no lists, no markdown, no stage directions.
- Respond only in English.

## CRITICAL INSTRUCTIONS
- NEVER mention tools, instructions, a brief or messages. NEVER say things like "still nothing" or "no word yet".
- NEVER invent facts or commitments that are not in the brief or in ${them}'s answers.
- NEVER call \`end_call\` before they've confirmed and you've said goodbye. ALWAYS call \`end_call\` right after your goodbye.`;
}

export function callerTools(principal: string) {
  return [
    { type: "function", name: "send_dtmf" },
    {
      type: "function",
      name: "request_input",
      description: `Ask ${principal} something you can't answer or decide yourself. Say a short stall line to the other person first. ${principal}'s answer arrives later through check_messages.`,
      parameters: {
        type: "object",
        properties: {
          question: { type: "string", description: `A self-contained question for ${principal}, including the options they gave you.` },
        },
        required: ["question"],
      },
    },
    {
      type: "function",
      name: "check_messages",
      description: `Get ${principal}'s answers to questions you asked with request_input.`,
      parameters: { type: "object", properties: {} },
    },
    {
      type: "function",
      name: "end_call",
      description: "Hang up. Call it in the same turn as your goodbye.",
      parameters: {
        type: "object",
        properties: {
          outcome: { type: "string", enum: ["done", "partial", "not_done", "voicemail", "wrong_number", "refused"] },
          notes: { type: "string", description: "What happened, with any key details like times, prices, names or confirmation numbers." },
        },
        required: ["outcome", "notes"],
      },
    },
  ];
}

// A second Grok agent that plays the person being called, for test calls without a human.
export function simulatedCalleeInstructions(persona: string): string {
  return `## Role & Persona
You are answering the phone at work. ${persona.trim()}

## Conversation Flow
- Answer the phone the way this person would, for example with the business name.
- Respond to the caller naturally. Ask the questions this person would ask.
- If the caller says goodbye, say bye.

## Voice & Communication Style
- You are a busy real person: short, casual sentences, one or two per turn.
- Respond only in English.`;
}

export function summaryPrompt(job: Job, transcript: string, questions: string): string {
  return `${job.principal} asked an assistant (${job.agentName}) to make a phone call to ${job.to}. Write the after-call report.

Brief:
${job.brief.trim()}

Questions the assistant asked ${job.principal} during the call:
${questions || "(none)"}

The assistant's own end-of-call note: ${job.endCall ? JSON.stringify(job.endCall) : "(none)"}
Call status: ${job.twilioStatus ?? "unknown"}, duration ${job.durationSec ?? "?"}s.

Transcript (${job.agentName} is the assistant, Them is the other side):
${transcript || "(empty)"}

Reply with JSON only:
{
  "outcome": "done" | "partial" | "not_done" | "voicemail" | "no_answer" | "wrong_number" | "refused" | "failed",
  "summary": "2-4 plain sentences: what happened and where things stand",
  "details": { "key": "value" pairs of concrete facts learned, like times, prices, names, confirmation numbers },
  "commitments": ["anything agreed to on ${job.principal}'s behalf"],
  "follow_ups": ["anything ${job.principal} still needs to do or decide"]
}
Use only what is in the transcript. Leave arrays empty when there is nothing.`;
}

import type { Env, JobEvent } from "./types";

const E164 = /^\+[1-9]\d{7,14}$/;

export function job(env: Env, id: string) {
  return env.CALL_JOB.get(env.CALL_JOB.idFromName(id));
}

export function registry(env: Env) {
  return env.REGISTRY.get(env.REGISTRY.idFromName("main"));
}

export interface StartRequest {
  to?: string;
  brief?: string;
  principal?: string;
  agent_name?: string;
  voice?: string;
  max_minutes?: number;
  answer_timeout?: number;
  simulate?: string;
}

export async function startJob(env: Env, origin: string, input: StartRequest): Promise<{ job_id: string } | { error: string; status: number }> {
  const simulate = typeof input.simulate === "string" && input.simulate.trim() ? input.simulate.trim() : undefined;
  if (!simulate && !E164.test(input.to ?? "")) return { error: "to must be an E.164 number like +14155550100", status: 400 };
  if (simulate && !env.SIM_NUMBER) return { error: "simulated calls need a SIM_NUMBER; run npm run setup again with simulation on", status: 400 };
  if (!input.principal && !env.PRINCIPAL_NAME) return { error: "say who the call is for: pass `for`, or set the PRINCIPAL_NAME secret", status: 400 };
  if (typeof input.brief !== "string" || !input.brief.trim()) return { error: "brief is required", status: 400 };
  if (input.brief.length > 8000) return { error: "brief is too long (8000 chars max)", status: 400 };
  const id = `job_${crypto.randomUUID().replaceAll("-", "").slice(0, 12)}`;
  const result = await job(env, id).start({
    id,
    to: simulate ? "simulated" : input.to!,
    brief: input.brief,
    origin,
    principal: input.principal,
    agentName: input.agent_name,
    voice: input.voice,
    maxMinutes: input.max_minutes,
    answerTimeoutSec: input.answer_timeout,
    simulate,
  });
  return "error" in result ? { error: result.error, status: 502 } : { job_id: id };
}

// Waits until the agent has a question, the call is over, or the deadline passes.
export async function waitForTurn(env: Env, jobId: string, after: number, timeoutMs: number) {
  const stub = job(env, jobId);
  const deadline = Date.now() + timeoutMs;
  const lines: string[] = [];
  let cursor = after;
  for (;;) {
    const r = await stub.watch(cursor, Math.max(0, Math.min(deadline - Date.now(), 25_000)));
    if (!r) return null;
    for (const e of r.events as unknown as JobEvent[]) {
      const line = describe(e);
      if (line) lines.push(line);
    }
    cursor = r.cursor;
    if (r.pending.length) return { type: "input_request", job_id: jobId, question_id: r.pending[0].id, question: r.pending[0].question, cursor, progress: lines };
    if (r.status === "done") return { type: "done", job_id: jobId, report: r.report, cursor, progress: lines };
    if (Date.now() >= deadline) return { type: "running", job_id: jobId, status: r.status, cursor, progress: lines };
  }
}

export function describe(e: JobEvent): string | null {
  const d = e.data as Record<string, any>;
  switch (e.type) {
    case "status":
      return `· ${d.status}${d.reason ? ` (${d.reason})` : ""}`;
    case "said":
      return `${d.who === "agent" ? "agent" : "them"}: ${d.text}`;
    case "input_request":
      return `? ${d.id}: ${d.question}`;
    case "answer":
      return `↳ ${d.id}: ${d.answer}${d.late ? " (late)" : ""}`;
    case "input_timeout":
      return `! ${d.id} timed out without an answer`;
    case "end_call":
      return `· agent hung up: ${d.outcome}`;
    case "error":
      return `! ${d.message}`;
    default:
      return null;
  }
}

import { CallJob } from "./call-job";
import { job, registry, startJob } from "./jobs";
import { handleMcp } from "./mcp";
import { Registry } from "./registry";
import type { Env } from "./types";
import { safeEqual, verifyStandardWebhook, verifyTwilio } from "./verify";

export { CallJob, Registry };

const json = (data: unknown, status = 200) => Response.json(data, { status });

export default {
  async fetch(req, env, ctx): Promise<Response> {
    const url = new URL(req.url);
    const [root, a, b] = url.pathname.split("/").filter(Boolean);

    if (root === "twilio" && a === "status" && b && req.method === "POST") {
      const params = new URLSearchParams(await req.text());
      if (!(await verifyTwilio(env.TWILIO_AUTH_TOKEN, url.toString(), params, req.headers.get("x-twilio-signature")))) return new Response("bad signature", { status: 403 });
      await job(env, b).twilioStatus(Object.fromEntries(params));
      return new Response(null, { status: 204 });
    }

    if (root === "xai" && a === "webhook" && req.method === "POST") {
      const body = await req.text();
      if (!(await verifyStandardWebhook(env.XAI_WEBHOOK_SECRET, req.headers, body))) return new Response("bad signature", { status: 403 });
      const event = JSON.parse(body);
      if (event.type !== "realtime.call.incoming") return new Response(null, { status: 204 });
      const headers: { name: string; value: string }[] = event.data?.sip_headers ?? [];
      const header = (name: string) => headers.find((h) => h.name.toLowerCase() === name.toLowerCase())?.value;
      const simJob = header("X-Sim-Job");
      const role = simJob || (env.SIM_NUMBER && header("To")?.includes(env.SIM_NUMBER)) ? "sim" : "agent";
      const jobId = role === "sim" ? simJob : (header("X-Job-Id") ?? (await registry(env).unattached()));
      if (!jobId) return json({ error: "no job for this call" }, 404);
      ctx.waitUntil(job(env, jobId).attach(event.data.call_id, role, headers.map((h) => h.name)));
      return new Response(null, { status: 204 });
    }

    if (root !== "jobs" && root !== "mcp") return new Response("not found", { status: 404 });
    if (!safeEqual(req.headers.get("authorization") ?? "", `Bearer ${env.PHONECALL_TOKEN}`)) return json({ error: "unauthorized" }, 401);
    if (root === "mcp") return handleMcp(req, env, url.origin);

    if (!a && req.method === "GET") return json(await registry(env).list(Number(url.searchParams.get("limit") ?? 20)));
    if (!a && req.method === "POST") {
      const result = await startJob(env, url.origin, await req.json());
      return "error" in result ? json({ error: result.error }, result.status) : json(result, 201);
    }

    const stub = job(env, a);
    if (!b && req.method === "GET") {
      const report = await stub.report();
      return report ? json(report) : json({ error: "unknown job" }, 404);
    }
    if (b === "watch" && req.method === "GET") {
      const after = Number(url.searchParams.get("after") ?? 0);
      const timeout = Math.min(Number(url.searchParams.get("timeout") ?? 25), 50) * 1000;
      const result = await stub.watch(after, timeout);
      return result ? json(result) : json({ error: "unknown job" }, 404);
    }
    if (b === "reply" && req.method === "POST") {
      const { question_id, answer } = await req.json<{ question_id?: string; answer?: string }>();
      if (!question_id || typeof answer !== "string") return json({ error: "question_id and answer are required" }, 400);
      const result = await stub.reply(question_id, answer);
      return json(result, "error" in result ? 400 : 200);
    }
    if (b === "hangup" && req.method === "POST") return json(await stub.hangup());
    return new Response("not found", { status: 404 });
  },
} satisfies ExportedHandler<Env>;

const enc = new TextEncoder();

function b64(bytes: ArrayBuffer): string {
  let s = "";
  for (const b of new Uint8Array(bytes)) s += String.fromCharCode(b);
  return btoa(s);
}

function fromB64(s: string): Uint8Array {
  return Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
}

export function safeEqual(a: string, b: string): boolean {
  const x = enc.encode(a);
  const y = enc.encode(b);
  if (x.length !== y.length) return false;
  let diff = 0;
  for (let i = 0; i < x.length; i++) diff |= x[i] ^ y[i];
  return diff === 0;
}

async function hmac(hash: "SHA-1" | "SHA-256", key: Uint8Array, data: string): Promise<string> {
  const k = await crypto.subtle.importKey("raw", key, { name: "HMAC", hash }, false, ["sign"]);
  return b64(await crypto.subtle.sign("HMAC", k, enc.encode(data)));
}

// https://www.twilio.com/docs/usage/security#validating-requests
export async function verifyTwilio(authToken: string, url: string, params: URLSearchParams, signature: string | null): Promise<boolean> {
  if (!signature) return false;
  const keys = [...new Set(params.keys())].sort();
  let data = url;
  for (const k of keys) for (const v of params.getAll(k)) data += k + v;
  return safeEqual(await hmac("SHA-1", enc.encode(authToken), data), signature);
}

// Standard Webhooks signatures (webhook-id, webhook-timestamp, webhook-signature).
// `secrets` is comma-separated: xAI creates one webhook, with its own secret, per registered number.
export async function verifyStandardWebhook(secrets: string, headers: Headers, body: string): Promise<boolean> {
  const id = headers.get("webhook-id");
  const ts = headers.get("webhook-timestamp");
  const sigs = headers.get("webhook-signature");
  if (!id || !ts || !sigs) return false;
  if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) return false;
  for (const secret of secrets.split(",")) {
    const key = secret.startsWith("whsec_") ? fromB64(secret.slice(6)) : enc.encode(secret);
    const expected = await hmac("SHA-256", key, `${id}.${ts}.${body}`);
    if (sigs.split(" ").some((s) => safeEqual(s.split(",")[1] ?? "", expected))) return true;
  }
  return false;
}

import { DurableObject } from "cloudflare:workers";
import { callerInstructions, callerTools, simulatedCalleeInstructions, summaryPrompt } from "./prompt";
import type { Env, Job, JobEvent, JobStatus, Question, Report } from "./types";

const TERMINAL = new Set(["completed", "busy", "no-answer", "failed", "canceled"]);
// Rough speaking rate, used to wait for the goodbye to finish playing before hanging up.
const MS_PER_CHAR = 70;

export interface StartInput {
  id: string;
  to: string;
  brief: string;
  origin: string;
  principal?: string;
  agentName?: string;
  voice?: string;
  maxMinutes?: number;
  answerTimeoutSec?: number;
  simulate?: string;
}

type Answer = { question: string; answer: string | null; note?: string };

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, Math.round(n)));
const xml = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const send = (ws: WebSocket | null, msg: unknown) => ws?.send(JSON.stringify(msg));

// One phone call: dials through Twilio, runs the Grok voice session, collects questions and the transcript.
export class CallJob extends DurableObject<Env> {
  job: Job | null = null;
  agent: WebSocket | null = null;
  sim: WebSocket | null = null;
  responseActive = false;
  userSpeaking = false;
  responseStartedAt = 0;
  audioEndsAt = 0;
  hangupPending = false;
  openerTimer: ReturnType<typeof setTimeout> | null = null;
  queue: Answer[] = [];
  waiters = new Set<() => void>();
  seenTypes = new Set<string>();
  finalizing: Promise<void> | null = null;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.storage.sql.exec(`CREATE TABLE IF NOT EXISTS events (seq INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER, type TEXT, data TEXT)`);
    ctx.storage.sql.exec(`CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, question TEXT, status TEXT, answer TEXT, asked_at INTEGER, answered_at INTEGER)`);
    ctx.blockConcurrencyWhile(async () => {
      this.job = (await ctx.storage.get<Job>("job")) ?? null;
    });
  }

  private registry() {
    return this.env.REGISTRY.get(this.env.REGISTRY.idFromName("main"));
  }

  private async save() {
    await this.ctx.storage.put("job", this.job);
  }

  private emit(type: string, data: Record<string, unknown> = {}) {
    this.ctx.storage.sql.exec(`INSERT INTO events (at, type, data) VALUES (?, ?, ?)`, Date.now(), type, JSON.stringify(data));
    for (const wake of this.waiters) wake();
    this.waiters.clear();
  }

  private setStatus(status: JobStatus, extra: Record<string, unknown> = {}) {
    if (!this.job || this.job.status === status) return;
    this.job.status = status;
    this.emit("status", { status, ...extra });
    this.ctx.waitUntil(this.registry().update(this.job.id, { status }));
  }

  private events(after: number): JobEvent[] {
    return this.ctx.storage.sql
      .exec<{ seq: number; at: number; type: string; data: string }>(`SELECT * FROM events WHERE seq > ? ORDER BY seq`, after)
      .toArray()
      .map((r) => ({ seq: r.seq, at: r.at, type: r.type, data: JSON.parse(r.data) }));
  }

  private questions(status?: Question["status"]): Question[] {
    const rows = status
      ? this.ctx.storage.sql.exec(`SELECT * FROM questions WHERE status = ? ORDER BY asked_at`, status)
      : this.ctx.storage.sql.exec(`SELECT * FROM questions ORDER BY asked_at`);
    return rows.toArray().map((r) => ({
      id: r.id as string,
      question: r.question as string,
      status: r.status as Question["status"],
      answer: r.answer as string | null,
      askedAt: r.asked_at as number,
      answeredAt: r.answered_at as number | null,
    }));
  }

  // ---- API ----

  async start(input: StartInput): Promise<{ ok: true } | { error: string }> {
    if (this.job) return { error: "job already exists" };
    const env = this.env;
    this.job = {
      id: input.id,
      to: input.to,
      brief: input.brief,
      principal: input.principal || env.PRINCIPAL_NAME || "",
      agentName: input.agentName || env.AGENT_NAME || "Sam",
      voice: input.voice || env.VOICE || "eve",
      maxMinutes: clamp(input.maxMinutes ?? 10, 1, 30),
      answerTimeoutSec: clamp(input.answerTimeoutSec ?? 60, 10, 300),
      simulate: input.simulate,
      origin: input.origin,
      status: "dialing",
      createdAt: Date.now(),
    };
    await this.save();
    await this.registry().add(this.job.id, this.job.to, this.job.brief);
    this.emit("status", { status: "dialing", to: this.job.to, simulated: !!this.job.simulate });
    // Backstop in case Twilio's final status callback never arrives.
    await this.ctx.storage.setAlarm(Date.now() + (this.job.maxMinutes + 5) * 60_000);

    // When the callee answers, Twilio bridges them to our xAI SIP number; the header tells the webhook which job it is.
    const agentUri = `sip:${env.TWILIO_PHONE_NUMBER}@sip.voice.x.ai;transport=tls?X-Job-Id=${this.job.id}`;
    const params = new URLSearchParams({
      From: env.TWILIO_PHONE_NUMBER,
      To: this.job.simulate ? `sip:${env.SIM_NUMBER}@sip.voice.x.ai;transport=tls?X-Sim-Job=${this.job.id}` : this.job.to,
      Twiml: `<Response><Dial><Sip username="${xml(env.SIP_USERNAME)}" password="[REDACTED]}">${xml(agentUri)}</Sip></Dial></Response>`,
      StatusCallback: `${this.job.origin}/twilio/status/${this.job.id}`,
      StatusCallbackMethod: "POST",
      Timeout: "30",
      TimeLimit: String(this.job.maxMinutes * 60),
    });
    for (const e of ["initiated", "ringing", "answered", "completed"]) params.append("StatusCallbackEvent", e);
    if (this.job.simulate) {
      params.set("SipAuthUsername", env.SIP_USERNAME);
      params.set("SipAuthPassword", env.SIP_PASSWORD);
    }
    const res = await this.twilio("Calls.json", params);
    const body = await res.json<{ sid?: string; message?: string }>();
    if (!res.ok || !body.sid) {
      this.emit("error", { message: `Twilio refused the call: ${body.message ?? res.status}` });
      await this.finalize("failed");
      return { error: body.message ?? `twilio ${res.status}` };
    }
    this.job.twilioCallSid = body.sid;
    await this.save();
    return { ok: true };
  }

  async twilioStatus(p: Record<string, string>) {
    if (!this.job || this.job.status === "done") return;
    const s = p.CallStatus;
    this.job.twilioStatus = s;
    if (s === "ringing") this.setStatus("ringing");
    else if (s === "in-progress") {
      this.job.answeredAt = Date.now();
      this.setStatus("connected");
    } else if (TERMINAL.has(s)) {
      this.job.durationSec = Number(p.CallDuration ?? 0);
      await this.save();
      await this.finalize(s);
      return;
    }
    await this.save();
  }

  async attach(callId: string, role: "agent" | "sim", sipHeaders: string[]): Promise<{ ok: true } | { error: string }> {
    if (!this.job || this.job.status === "done" || this.job.status === "ended") return { error: "no live job" };
    if (role === "agent" ? this.agent : this.sim) return { error: "already attached" };
    this.emit("debug", { sip_leg: role, sip_headers: sipHeaders });
    if (role === "agent") this.job.xaiCallId = callId;
    else this.job.simCallId = callId;
    await this.save();

    const res = await fetch(`https://api.x.ai/v1/realtime?call_id=${encodeURIComponent(callId)}`, {
      headers: { Upgrade: "websocket", Authorization: `Bearer ${this.env.XAI_API_KEY}` },
    });
    const ws = res.webSocket;
    if (!ws) {
      this.emit("error", { message: `xAI realtime connect failed (${role}): ${res.status} ${(await res.text()).slice(0, 200)}` });
      return { error: "xai connect failed" };
    }
    ws.accept();
    if (role === "agent") {
      this.agent = ws;
      await this.registry().update(this.job.id, { attached: true });
      this.setupAgent(ws);
    } else {
      this.sim = ws;
      this.setupSim(ws);
    }
    return { ok: true };
  }

  async watch(after: number, timeoutMs: number) {
    if (!this.job) return null;
    let events = this.events(after);
    if (!events.length && this.job.status !== "done" && !this.questions("pending").length) {
      await new Promise<void>((resolve) => {
        this.waiters.add(resolve);
        setTimeout(resolve, timeoutMs);
      });
      events = this.events(after);
    }
    return {
      status: this.job.status,
      cursor: events.at(-1)?.seq ?? after,
      events,
      pending: this.questions("pending"),
      report: this.job.report ?? null,
    };
  }

  async reply(questionId: string, answer: string): Promise<{ ok: true; delivered: boolean } | { error: string }> {
    const q = this.questions().find((x) => x.id === questionId);
    if (!q) return { error: `unknown question ${questionId}` };
    if (q.status === "answered") return { error: `${questionId} is already answered` };
    this.ctx.storage.sql.exec(`UPDATE questions SET status = 'answered', answer = ?, answered_at = ? WHERE id = ?`, answer, Date.now(), questionId);
    this.emit("answer", { id: questionId, answer, late: q.status === "timed_out" });
    if (!this.agent) return { ok: true, delivered: false };
    this.queue.push({ question: q.question, answer });
    this.flush();
    return { ok: true, delivered: true };
  }

  async hangup() {
    if (!this.job) return { error: "unknown job" };
    this.emit("status", { status: "hangup_requested" });
    await this.endCall();
    return { ok: true };
  }

  async report() {
    if (!this.job) return null;
    const { origin: _origin, ...job } = this.job;
    return {
      job,
      questions: this.questions(),
      transcript: this.events(0)
        .filter((e) => e.type === "said")
        .map((e) => ({ at: e.at, who: e.data.who, text: e.data.text })),
    };
  }

  async alarm() {
    if (this.job && this.job.status !== "done") {
      await this.endCall();
      await this.finalize("timeout");
    }
  }

  // ---- Voice session ----

  private setupAgent(ws: WebSocket) {
    const job = this.job!;
    ws.addEventListener("message", (m) => {
      if (typeof m.data === "string") this.onAgentEvent(JSON.parse(m.data));
    });
    ws.addEventListener("close", (e) => {
      this.agent = null;
      this.emit("status", { status: "voice_session_closed", code: e.code });
    });
    send(ws, {
      type: "session.update",
      session: {
        instructions: callerInstructions(job),
        voice: job.voice,
        turn_detection: { type: "server_vad" },
        tools: callerTools(job.principal),
      },
    });
    // The callee usually said "hello" before the bridge connected; open if they don't speak again.
    this.openerTimer = setTimeout(() => {
      if (!this.responseActive && !this.userSpeaking) this.respond();
    }, 1500);
  }

  // The transcript records what our agent heard, so a simulated call exercises the same path as a real one.
  private setupSim(ws: WebSocket) {
    ws.addEventListener("close", () => {
      this.sim = null;
    });
    send(ws, {
      type: "session.update",
      session: { instructions: simulatedCalleeInstructions(this.job!.simulate!), voice: "rex", turn_detection: { type: "server_vad" } },
    });
    send(ws, { type: "response.create" });
  }

  private onAgentEvent(e: any) {
    // Events still buffered after the call ended were never heard by anyone.
    if (!this.job || this.job.status === "ended" || this.job.status === "done") return;
    switch (e.type) {
      case "response.created":
        this.responseActive = true;
        this.responseStartedAt = Date.now();
        break;
      case "response.output_audio.delta":
      case "response.output_audio_transcript.delta":
      case "response.function_call_arguments.delta":
      case "input_audio_buffer.append":
      case "ping":
        break;
      case "response.output_audio_transcript.done": {
        const text = e.transcript?.trim();
        if (!text) break;
        this.emit("said", { who: "agent", text });
        this.audioEndsAt = Math.max(this.audioEndsAt, this.responseStartedAt + text.length * MS_PER_CHAR);
        break;
      }
      case "conversation.item.added": {
        // xAI puts the caller's transcript on the committed user item; there is no separate transcription event.
        const item = e.item ?? {};
        if (item.role !== "user" || item.type !== "message") break;
        const text = (item.content ?? [])
          .filter((c: any) => c.type === "input_audio")
          .map((c: any) => c.transcript ?? "")
          .join(" ")
          .trim();
        if (text) this.emit("said", { who: "them", text });
        break;
      }
      case "input_audio_buffer.speech_started":
        this.userSpeaking = true;
        if (this.openerTimer) clearTimeout(this.openerTimer);
        break;
      case "input_audio_buffer.speech_stopped":
        this.userSpeaking = false;
        setTimeout(() => this.flush(), 400);
        break;
      case "response.function_call_arguments.done":
        this.onTool(e.name, e.call_id, e.arguments);
        break;
      case "response.done":
        this.responseActive = false;
        if (this.hangupPending) this.scheduleHangup();
        else this.flush();
        break;
      case "error":
        this.emit("error", { message: e.error?.message ?? JSON.stringify(e).slice(0, 300) });
        break;
      default:
        if (!this.seenTypes.has(e.type)) {
          this.seenTypes.add(e.type);
          this.emit("debug", { xai_event: e.type, sample: JSON.stringify(e).slice(0, 300) });
        }
    }
  }

  private onTool(name: string, callId: string, argsJson: string) {
    const job = this.job!;
    let args: Record<string, string> = {};
    try {
      args = JSON.parse(argsJson || "{}");
    } catch {}
    switch (name) {
      case "send_dtmf":
        // xAI sends the tones itself and expects no reply.
        this.emit("dtmf", args);
        return;
      case "request_input": {
        const id = `q${this.questions().length + 1}`;
        this.ctx.storage.sql.exec(`INSERT INTO questions (id, question, status, asked_at) VALUES (?, ?, 'pending', ?)`, id, args.question ?? "", Date.now());
        this.emit("input_request", { id, question: args.question });
        this.output(callId, { status: "sent", note: `${job.principal} has your question. Don't say anything else about it unless they talk to you.` }, false);
        setTimeout(() => this.expireQuestion(id), job.answerTimeoutSec * 1000);
        return;
      }
      case "check_messages": {
        const answers = this.queue.splice(0);
        // With nothing to report, stay quiet instead of prompting a turn ("Still nothing...").
        if (answers.length) this.output(callId, { answers }, true);
        else this.output(callId, { answers: [], note: `${job.principal} is still checking. Don't comment on it; carry on only if they talk to you.` }, false);
        return;
      }
      case "end_call":
        job.endCall = { outcome: args.outcome ?? "done", notes: args.notes };
        this.ctx.waitUntil(this.save());
        this.emit("end_call", job.endCall);
        this.output(callId, { ok: true }, false);
        this.hangupPending = true;
        if (!this.responseActive) this.scheduleHangup();
        return;
      default:
        this.output(callId, { error: `unknown tool ${name}` }, true);
    }
  }

  private output(callId: string, result: unknown, respond: boolean) {
    send(this.agent, { type: "conversation.item.create", item: { type: "function_call_output", call_id: callId, output: JSON.stringify(result) } });
    if (respond) this.respond();
  }

  private respond() {
    if (!this.agent) return;
    send(this.agent, { type: "response.create" });
    this.responseActive = true;
  }

  // Deliver answers as a check_messages tool result. A plain system message gets ignored by the model.
  private flush() {
    if (!this.agent || this.responseActive || this.userSpeaking || this.hangupPending || !this.queue.length) return;
    const answers = this.queue.splice(0);
    const callId = `call-msg-${Date.now()}`;
    send(this.agent, { type: "conversation.item.create", item: { type: "function_call", call_id: callId, name: "check_messages", arguments: "{}" } });
    send(this.agent, { type: "conversation.item.create", item: { type: "function_call_output", call_id: callId, output: JSON.stringify({ answers }) } });
    this.respond();
  }

  private expireQuestion(id: string) {
    const q = this.questions("pending").find((x) => x.id === id);
    if (!q || !this.job) return;
    this.ctx.storage.sql.exec(`UPDATE questions SET status = 'timed_out' WHERE id = ?`, id);
    this.emit("input_timeout", { id });
    this.queue.push({ question: q.question, answer: null, note: `${this.job.principal} didn't answer in time. Say you'll have to get back to them on that part and keep going.` });
    this.flush();
  }

  private scheduleHangup() {
    const wait = Math.max(this.audioEndsAt - Date.now(), 0) + 1200;
    setTimeout(() => this.ctx.waitUntil(this.endCall()), wait);
  }

  private async endCall() {
    const job = this.job;
    if (!job) return;
    if (job.xaiCallId) {
      const res = await fetch(`https://api.x.ai/v1/realtime/calls/${job.xaiCallId}/hangup`, {
        method: "POST",
        headers: { Authorization: `Bearer ${this.env.XAI_API_KEY}` },
      });
      if (res.ok) return;
    }
    if (job.twilioCallSid) {
      const status = job.status === "connected" ? "completed" : "canceled";
      await this.twilio(`Calls/${job.twilioCallSid}.json`, new URLSearchParams({ Status: status }));
    }
  }

  private twilio(path: string, body: URLSearchParams) {
    const { TWILIO_ACCOUNT_SID: sid, TWILIO_AUTH_TOKEN: token } = this.env;
    return fetch(`https://api.twilio.com/2010-04-01/Accounts/${sid}/${path}`, {
      method: "POST",
      headers: { Authorization: `Basic ${btoa(`${sid}:${token}`)}`, "Content-Type": "application/x-www-form-urlencoded" },
      body,
    });
  }

  // ---- Wrap-up ----

  private finalize(reason: string): Promise<void> {
    if (!this.job || this.job.status === "done") return Promise.resolve();
    this.finalizing ??= (async () => {
      const job = this.job!;
      job.endedAt = Date.now();
      this.setStatus("ended", { reason });
      if (this.openerTimer) clearTimeout(this.openerTimer);
      for (const ws of [this.agent, this.sim]) {
        try {
          ws?.close(1000, "call ended");
        } catch {}
      }
      this.agent = this.sim = null;
      this.ctx.storage.sql.exec(`UPDATE questions SET status = 'timed_out' WHERE status = 'pending'`);
      job.report = await this.summarize(reason);
      await this.save();
      this.setStatus("done");
      this.emit("done", { report: job.report });
      await this.ctx.storage.deleteAlarm();
    })();
    return this.finalizing;
  }

  private async summarize(reason: string): Promise<Report> {
    const job = this.job!;
    const lines = this.events(0)
      .filter((e) => e.type === "said")
      .map((e) => `${e.data.who === "agent" ? job.agentName : "Them"}: ${e.data.text}`);
    const empty = (outcome: string, summary: string): Report => ({ outcome, summary, details: {}, commitments: [], follow_ups: [] });
    if (!lines.length) {
      if (reason === "busy") return empty("no_answer", "The line was busy.");
      if (reason === "no-answer") return empty("no_answer", "Nobody picked up.");
      if (reason === "completed") return empty("failed", "The call connected but nothing was said.");
      return empty("failed", `The call ended before anyone talked (${reason}).`);
    }
    const questions = this.questions()
      .map((q) => `- ${q.question} → ${q.answer ?? "(no answer)"}`)
      .join("\n");
    try {
      const res = await fetch("https://api.x.ai/v1/chat/completions", {
        method: "POST",
        headers: { Authorization: `Bearer ${this.env.XAI_API_KEY}`, "Content-Type": "application/json" },
        body: JSON.stringify({
          model: this.env.SUMMARY_MODEL || "grok-4.7",
          messages: [{ role: "user", content: summaryPrompt(job, lines.join("\n"), questions) }],
          response_format: { type: "json_object" },
        }),
      });
      const body = await res.json<any>();
      const parsed = JSON.parse(body.choices[0].message.content);
      return {
        outcome: parsed.outcome ?? job.endCall?.outcome ?? "partial",
        summary: parsed.summary ?? "",
        details: parsed.details ?? {},
        commitments: parsed.commitments ?? [],
        follow_ups: parsed.follow_ups ?? [],
      };
    } catch (err) {
      return empty(job.endCall?.outcome ?? "partial", `Summary failed (${String(err).slice(0, 120)}). Agent note: ${job.endCall?.notes ?? "none"}`);
    }
  }
}
